	/** 
	 * jumpstart the process by instantiating2 Model
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		modelId = ModelService.getModelInstance()
		.createModel( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ModelService.getModelInstance()
				.createModel( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.modelSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Model : " + successValue.getModelId());
							  if (successValue.getModelId().equals(modelId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfModelList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Model test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on model consumed")
					);
			subscriber.modelSubscribe( modelId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Model : " + successValue.getModelId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfModelList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on model for modelId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Model. 
	 */
	protected Model read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Model" );

		Model entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Model with primary key" );
		msg.append( modelId );
		
		ModelFetchOneSummary fetchOneSummary = new ModelFetchOneSummary( modelId );

		try {
			entity = ModelService.getModelInstance().getModel( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Model " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Model.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Model." );

		StringBuilder msg = new StringBuilder( "Failed to update a Model : " );        
		Model entity = read();
		UpdateModelCommand command = generateUpdateCommand();
		command.setModelId(entity.getModelId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Model." );

			// for use later on...
			modelId = entity.getModelId();

			ModelService proxy = ModelService.getModelInstance();  

			proxy.updateModel( command ).get();

			LOGGER.info( "-- Successfully saved Model - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + modelId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Model.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Model." );

		Model entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Model with id " + modelId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Model with id " + modelId );

			throw e;
		}

		try{
			ModelService.getModelInstance().delete( new DeleteModelCommand( entity.getModelId() ) ).get();
			LOGGER.info( "-- Successfully deleted Model with id " + modelId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Model with id " + modelId );

			throw e;
		}
	}

	/**
	 * get all Models.
	 */
	protected List<Model> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Models:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Model : " );        
		List<Model> collection  = new ArrayList<>();

		try {
			// call the static get method on the ModelService
			collection = ModelService.getModelInstance().getAllModel();
			assertNotNull( collection, "An Empty collection of Model was incorrectly returned.");
			
			// Now print out the values
			Model entity = null;            
			Iterator<Model> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getModelId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

